import{_ as e,o as a,c as r,a3 as o}from"./chunks/framework.BNNhFWPR.js";const f=JSON.parse('{"title":"Using the editor","description":"Create a project, build a scene, run it, and find your way around the editor.","frontmatter":{"id":"editor","title":"Using the editor","order":4,"description":"Create a project, build a scene, run it, and find your way around the editor.","editUrl":"https://github.com/ATMO-Engine/atmo/edit/main/docs/en/getting-started/editor.md"},"headers":[],"relativePath":"getting-started/editor.md","filePath":"en/getting-started/editor.md"}'),i={name:"getting-started/editor.md"};function s(d,t,n,h,l,c){return a(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="using-the-editor" tabindex="-1">Using the editor <a class="header-anchor" href="#using-the-editor" aria-label="Permalink to &quot;Using the editor&quot;">​</a></h1><h2 id="project" tabindex="-1">Create or open a project <a class="header-anchor" href="#project" aria-label="Permalink to &quot;Create or open a project {#project}&quot;">​</a></h2><p>Start the engine without options to get the project list:</p><ul><li>To create a project, type its name, then press <strong>Create new project</strong>.</li><li>To open one, press its path in the list.</li></ul><p>The list shows the projects of the <a href="/latest/getting-started/projects#location" class="atmo-ref atmo-ref--page" data-preview="Where projects are stored on your computer and how to reach their files with project:// paths.">projects folder</a>. Open any other one with <code>atmo --project /path/to/project</code>.</p><h2 id="window" tabindex="-1">The window <a class="header-anchor" href="#window" aria-label="Permalink to &quot;The window {#window}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Part</th><th>Contents</th></tr></thead><tbody><tr><td>Menus</td><td>File, Edit, Project and Debug. On macOS, they are in the system menu bar.</td></tr><tr><td>Tab bar</td><td>One tab per open editor, and <strong>+</strong> to open another one. Press a tab&#39;s icon to close it.</td></tr><tr><td>Editor</td><td>The active tab</td></tr><tr><td>Bottom toolbar</td><td>Play</td></tr></tbody></table><p>Closing a tab does not ask to save it.</p><h2 id="files" tabindex="-1">Open and save files <a class="header-anchor" href="#files" aria-label="Permalink to &quot;Open and save files {#files}&quot;">​</a></h2><p>Each kind of file has its editor:</p><table tabindex="0"><thead><tr><th>Editor</th><th>Extension</th><th>Documentation</th></tr></thead><tbody><tr><td><a href="/latest/api/cpp/class/atmo-editor-sceneeditor" class="atmo-ref atmo-ref--symbol">Scene editor</a></td><td><code>.ascn</code></td><td><a href="#scene-editor">This page</a></td></tr><tr><td><a href="/latest/api/cpp/class/atmo-editor-materialeditor" class="atmo-ref atmo-ref--symbol">Material editor</a></td><td><code>.material</code></td><td><a href="/latest/manual/shaders-and-materials" class="atmo-ref atmo-ref--page" data-preview="Write Slang shaders for sprites and post-processing, and set their parameters with materials.">Shaders and materials</a></td></tr><tr><td><a href="/latest/api/cpp/class/atmo-editor-textureeditor" class="atmo-ref atmo-ref--symbol">Texture editor</a></td><td><code>.atx</code></td><td><a href="/latest/manual/texture-editor" class="atmo-ref atmo-ref--page" data-preview="Draw images with layers and frames, import sprite sheets, and export images.">Texture editor</a></td></tr></tbody></table><ul><li><strong>+</strong> opens an empty editor.</li><li><strong>Open</strong> asks for a file. If the active tab has the right editor, the file replaces its contents; otherwise a new tab is opened.</li><li><strong>Save</strong> saves the active tab, and asks for a file the first time. Scenes get the <code>.ascn</code> extension when it is missing.</li></ul><p>Scripts and shaders are written in the text editor of your choice.</p><div class="danger custom-block"><p class="custom-block-title">DANGER</p><p>When a file cannot be loaded in an editor, the tab stays open and empty, and saving it replaces the file. Do not save after an error in the log. This concerns in particular prefabs, which <a href="/latest/manual/prefabs#change" class="atmo-ref atmo-ref--page" data-preview="Save an entity and its children to a file, and load copies of it from the editor or from scripts.">cannot be opened as scenes</a>, and <a href="/latest/manual/texture-editor#known-issues" class="atmo-ref atmo-ref--page" data-preview="Draw images with layers and frames, import sprite sheets, and export images.">.atx images</a>.</p></div><h2 id="shortcuts" tabindex="-1">Shortcuts <a class="header-anchor" href="#shortcuts" aria-label="Permalink to &quot;Shortcuts {#shortcuts}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Shortcut</th><th>Action</th></tr></thead><tbody><tr><td>Ctrl+S</td><td>Save</td></tr><tr><td>Ctrl+Shift+S</td><td>Save as</td></tr><tr><td>Ctrl+O</td><td>Open</td></tr><tr><td>Ctrl+Z</td><td>Undo, in a text field</td></tr><tr><td>Ctrl+Shift+Z</td><td>Redo, in a text field</td></tr><tr><td>Ctrl+Shift+P</td><td><a href="/latest/manual/project-settings" class="atmo-ref atmo-ref--page" data-preview="Every project setting, its default value and what it changes.">Project settings</a></td></tr><tr><td>Ctrl+Shift+D</td><td>Add demo entities to the scene</td></tr><tr><td>Ctrl+Q</td><td>Quit</td></tr></tbody></table><p>On macOS, use Cmd instead of Ctrl. Undo and redo only apply to the text being typed: changes to a scene cannot be undone.</p><h2 id="scene-editor" tabindex="-1">The scene editor <a class="header-anchor" href="#scene-editor" aria-label="Permalink to &quot;The scene editor {#scene-editor}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Part</th><th>Contents</th></tr></thead><tbody><tr><td>Left panel</td><td>The entity tree</td></tr><tr><td>Center</td><td>The viewport</td></tr><tr><td>Right panel</td><td>The inspector: components of the selected entity</td></tr></tbody></table><h3 id="viewport" tabindex="-1">Viewport <a class="header-anchor" href="#viewport" aria-label="Permalink to &quot;Viewport {#viewport}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Action</th><th>Effect</th></tr></thead><tbody><tr><td>Scroll</td><td>Move</td></tr><tr><td>Ctrl+scroll (Cmd on macOS), or pinch</td><td>Zoom</td></tr></tbody></table><p>The red and green lines are the axes of the world, and the white rectangle is the size of the game window. <code>x</code> grows to the right and <code>y</code> downwards. Entities cannot be selected or moved with the mouse in the viewport: use the tree and the inspector. UI entities are only visible in the game.</p><h3 id="tree" tabindex="-1">Entity tree <a class="header-anchor" href="#tree" aria-label="Permalink to &quot;Entity tree {#tree}&quot;">​</a></h3><p>The <strong>+</strong> button of the panel adds an entity to the scene. Each row has four buttons:</p><table tabindex="0"><thead><tr><th>Button</th><th>Effect</th></tr></thead><tbody><tr><td>Plus</td><td>Adds a child to the entity</td></tr><tr><td>Folder</td><td><a href="/latest/manual/prefabs#load-editor" class="atmo-ref atmo-ref--page" data-preview="Save an entity and its children to a file, and load copies of it from the editor or from scripts.">Loads a prefab</a> as a child</td></tr><tr><td>Disk</td><td><a href="/latest/manual/prefabs#create-editor" class="atmo-ref atmo-ref--page" data-preview="Save an entity and its children to a file, and load copies of it from the editor or from scripts.">Saves the entity as a prefab</a></td></tr><tr><td>Cross</td><td>Deletes the entity and its children, without confirmation</td></tr></tbody></table><p>Press a row to select the entity. The types are described in <a href="/latest/manual/entities" class="atmo-ref atmo-ref--page" data-preview="What each entity type is for, and the component fields it has.">Entities and components</a>.</p><h3 id="inspector" tabindex="-1">Inspector <a class="header-anchor" href="#inspector" aria-label="Permalink to &quot;Inspector {#inspector}&quot;">​</a></h3><p>The inspector shows the fields of each component of the selected entity. <strong>Add Script</strong> adds a <a href="/latest/manual/entities#script" class="atmo-ref atmo-ref--page" data-preview="What each entity type is for, and the component fields it has.">script</a> to it. Components cannot be added or removed otherwise: they come with the type of the entity.</p><p>Paths are typed by hand: write <a href="/latest/getting-started/projects#project-paths" class="atmo-ref atmo-ref--page" data-preview="Where projects are stored on your computer and how to reach their files with project:// paths.">project:// paths</a>. Some fields, such as the layout of UI entities, show their name without any way to change them: edit the scene file instead.</p><h2 id="play" tabindex="-1">Run the game <a class="header-anchor" href="#play" aria-label="Permalink to &quot;Run the game {#play}&quot;">​</a></h2><ol><li>Set <code>default_scene</code> in the <a href="/latest/manual/project-settings#app" class="atmo-ref atmo-ref--page" data-preview="Every project setting, its default value and what it changes.">project settings</a>, for example to <code>project://main.ascn</code>.</li><li>Save the open files: the game reads them from the disk.</li><li>Press Play. The game runs in its own window, and the button stops it.</li></ol><h2 id="first-game" tabindex="-1">A first game <a class="header-anchor" href="#first-game" aria-label="Permalink to &quot;A first game {#first-game}&quot;">​</a></h2><ol><li>Create a project.</li><li>Press <strong>+</strong> in the tab bar and choose the scene editor.</li><li>Add a <code>Sprite2d</code> with the <strong>+</strong> button of the tree, select it, and write <code>project://assets/atmo.png</code> in <code>texture_path</code>.</li><li>Set its <code>position</code> to (400, 300).</li><li>Save the scene as <code>main.ascn</code> in the project.</li><li>In the project settings, write <code>project://main.ascn</code> in <code>default_scene</code>, then press <strong>Apply</strong>.</li><li>Press Play.</li></ol><p>Then make it move with a script: see <a href="/latest/manual/scripting#first-script" class="atmo-ref atmo-ref--page" data-preview="Attach Luau scripts to entities and use the functions the engine calls.">A first script</a>.</p>',34)])])}const m=e(i,[["render",s]]);export{f as __pageData,m as default};
